query:
query RoomPlanDetailAmount($accommodationId: AccommodationIdScalar!, $roomId: RoomIdScalar!, $planId: PlanIdScalar!, $planUwanosePointVariation: PlanUwanosePointVariationScalar! = 0, $input: RoomPlanBookingInput!, $device: Device!, $isYahooMode: Boolean! = false, $preview: Boolean! = false, $currency: Currency!, $isInternationalSite: Boolean!) {
  accommodation(accommodationId: $accommodationId) {
    ...AmountAccommodation
    roomPlan(
      roomId: $roomId
      planId: $planId
      planUwanosePointVariation: $planUwanosePointVariation
    ) {
      plan {
        bookableDateTimeFrom
      }
      booking(input: $input) {
        amount(preview: $preview) {
          uwanosePoint
        }
      }
    }
  }
}

fragment PointBurdenBreakdownPointBurdenRates on PointBurdenRates {
  accommodation
  other
}

fragment BaseDiscountDescriptionAmountDetail on AmountDetail {
  baseDiscount {
    baseDiscount {
      rate {
        settings {
          rate
          days
        }
        type
      }
      expirationTo
      promotionEntry {
        id
      }
    }
    appliedRate
  }
  date
}

fragment UwanosePointDetailAmount2 on Amount2 {
  amount
  point
  uwanosePoint
}

fragment AccommodationAmountAmount2 on Amount2 {
  amount
  baseDiscountAmount
  baseDiscountRate
  baseDiscountAmountWithCurrency: baseDiscountAmount(currency: $currency) @include(if: $isInternationalSite)
  childACount
  childBCount
  childCCount
  childDCount
  childECount
  childFCount
  discountAmount
  discountAmountEarn
  discountAmountWithoutCoupon
  discountAmountWithCurrency: discountAmount(currency: $currency) @include(if: $isInternationalSite)
  instantPoint
  instantPointRate
  lodgingCount
  peopleCount
  point
  pointRate
  roomCount
  uwanosePoint
  pointBurdenRates {
    ...PointBurdenBreakdownPointBurdenRates
  }
  zenkokuCoupon {
    displayName
    discountRate
    status
  }
  coupon {
    price
  }
  plan {
    meal {
      code
      name
    }
    sale
  }
  details {
    ...BaseDiscountDescriptionAmountDetail
  }
  ...UwanosePointDetailAmount2
}

fragment AmountDetailsAmountDetail on AmountDetail {
  date
  rooms {
    familyCount {
      people
      childA
      childB
      childC
      childD
      childE
      childF
    }
    roomSet
    room
    familyUnit {
      people
      childA
      childB
      childC
      childD
      childE
      childF
    }
  }
}

fragment AmountAccommodation on Accommodation {
  accommodationId
  allowInstantDiscount
  isDaiwaRoynet
  roomPlan(
    roomId: $roomId
    planId: $planId
    planUwanosePointVariation: $planUwanosePointVariation
  ) {
    booking(input: $input) {
      amount(preview: $preview) {
        ...AccommodationAmountAmount2
        amount
        baseDiscountAmount
        baseDiscountRate
        discountAmount
        instantPoint
        instantPointRate
        inventory
        peopleCount
        point
        pointRate
        details {
          ...BaseDiscountDescriptionAmountDetail
          ...AmountDetailsAmountDetail @include(if: $isYahooMode)
        }
        uwanosePoint
      }
      urlPath(device: $device)
      error
    }
  }
}
